using Decont;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using System.Security.Claims;
using Xunit;

namespace Decont.Tests;
public class Pdf05WorkflowTests {
 static ClaimsPrincipal Actor(string id,string role)=>new(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,id),new(ClaimTypes.Role,role)],"test"));
 static ExpenseData Data(decimal amount,string payment="Personal")=>new("",null,"R1","2026-01-01","DE","Receipt","GENERAL","Business expense",payment,null,"CC",null,amount,"RON",[],false);
 [Theory][InlineData("ABCDEF12",true)][InlineData("abcdef12",true)][InlineData("ABCDE12",false)][InlineData("ABCDEF123",false)][InlineData("ABCDEF12\n",false)][InlineData("ȘBCDEF12",false)][InlineData("ABCDEF١٢",false)]
 public void ExactLantIdFormat(string id,bool valid){if(valid)EmployeeIdentity.Format(id);else Assert.Throws<DomainException>(()=>EmployeeIdentity.Format(id));}
 [Fact]public async Task LantIdOwnershipIsCaseInsensitive(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var alice=await db.Users.SingleAsync(u=>u.UserName=="alice");await EmployeeIdentity.Validate(db,alice.Worker.ToLowerInvariant(),alice.Id);var error=await Assert.ThrowsAsync<DomainException>(()=>EmployeeIdentity.Validate(db,alice.Worker.ToUpperInvariant()));Assert.Equal("lantid_duplicate",error.Code);}
 [Theory][InlineData(49.99,false)][InlineData(50,false)][InlineData(50.01,true)][InlineData(-50,false)][InlineData(-50.01,true)]
 public async Task CorrectionThresholdIsAbsoluteStrictlyAbove50ForBothPaymentMethods(decimal difference,bool requires){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();foreach(var payment in new[]{"Personal","CompanyCard"}){var r=new Report{State=States.Finance,Lines=[new(){EstimatedRon=100,Json=Serialization.Write(Data(100,payment))}]};db.Reports.Add(r);var svc=new Reports(db);svc.Snapshot(r,Actor("employee","Employee"));await db.SaveChangesAsync();r.Lines[0].Json=Serialization.Write(Data(100+difference,payment));r.Lines[0].EstimatedRon=100+difference;var impact=await ApprovalWorkflow.Impact(db,r);Assert.Equal(requires,impact.RequiresReapproval);Assert.Equal(difference,impact.DifferenceRon);}}
 [Fact]public async Task CumulativeCorrectionsAndPreviewCannotBypassThreshold(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var r=new Report{State=States.Finance,Lines=[new(){EstimatedRon=100,Json=Serialization.Write(Data(100))}]};db.Reports.Add(r);new Reports(db).Snapshot(r,Actor("employee","Employee"));await db.SaveChangesAsync();r.Lines[0].Json=Serialization.Write(Data(130));r.Lines[0].EstimatedRon=130;await db.SaveChangesAsync();var impact=await ApprovalWorkflow.Impact(db,r,new(r.Lines[0].Id,Data(160)));Assert.True(impact.RequiresReapproval);Assert.Equal(60,impact.DifferenceRon);Assert.Equal(130,r.Lines[0].Data().Amount);var ex=await Assert.ThrowsAsync<DomainException>(()=>new Reports(db).Reapproval(new Report{State=States.Finance,ApprovedPersonal=1,Lines=[new(){EstimatedRon=100}]},Actor("finance","Finance")));Assert.Equal("reapproval_confirmation",ex.Code);}
 [Fact]public async Task FxOnlyAndVatOnlyCorrectionsKeepManagerApproval(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var r=new Report{State=States.Finance,Lines=[new(){EstimatedRon=100,Json=Serialization.Write(Data(100))}]};db.Reports.Add(r);new Reports(db).Snapshot(r,Actor("employee","Employee"));await db.SaveChangesAsync();r.Lines[0].FinanceRon=9999;r.Lines[0].Json=Serialization.Write(Data(100) with{Description="Accounting VAT correction",Taxes=[new(Guid.NewGuid(),82.64m,17.36m)]});var impact=await ApprovalWorkflow.Impact(db,r);Assert.Equal(0,impact.DifferenceRon);Assert.False(impact.RequiresReapproval);}
 [Fact]public async Task DatedManagerResolutionDoesNotUseStaleProfile(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var alice=await db.Users.SingleAsync(u=>u.UserName=="alice");alice.ManagerId="stale-profile";var route=await ApprovalWorkflow.Resolve(db,alice.Id,DateOnly.FromDateTime(DateTime.UtcNow));Assert.Equal("manager",route.Manager.UserName);Assert.NotEqual(alice.ManagerId,route.Manager.Id);}
 [Fact]public async Task MissingAssignmentDoesNotFallbackToProfileAndCycleIsRejected(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var alice=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var cycle=await Assert.ThrowsAsync<DomainException>(()=>ApprovalWorkflow.ValidateAssignment(db,manager.Id,alice.Id,new(2020,1,1),null));Assert.Equal("manager_cycle",cycle.Code);await db.Assignments.Where(a=>a.UserId==alice.Id).ExecuteDeleteAsync();var missing=await Assert.ThrowsAsync<DomainException>(()=>ApprovalWorkflow.Resolve(db,alice.Id,DateOnly.FromDateTime(DateTime.UtcNow)));Assert.Equal("manager_assignment",missing.Code);}
 [Fact]public async Task ApprovalAuthorityAndRevisionAreFrozenAndReturnIsNotReject(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var route=await ApprovalWorkflow.Resolve(db,employee.Id,DateOnly.FromDateTime(DateTime.UtcNow));var r=new Report{EmployeeId=employee.Id,ManagerId=route.Manager.Id,State=States.Manager};db.Reports.Add(r);var svc=new Reports(db);svc.Snapshot(r,Actor(employee.Id,"Employee"));await db.SaveChangesAsync();await ApprovalWorkflow.CreateTask(db,svc,r,Actor(employee.Id,"Employee"),route);await db.SaveChangesAsync();Assert.True(await svc.Manager(r,Actor(route.Manager.Id,"Manager")));Assert.False(await svc.Manager(r,Actor(employee.Id,"Manager")));Assert.False(await svc.Manager(r,Actor("other","Manager")));var task=await db.ApprovalTasks.SingleAsync();var frozen=await db.ApprovalRoutes.SingleAsync();Assert.Equal(r.Revision,frozen.Revision);Assert.Equal(route.Assignment.Id,frozen.AssignmentId);await svc.Action(r,Actor(route.Manager.Id,"Manager"),"return","Correct the receipt description");await db.SaveChangesAsync();Assert.Equal(States.Returned,r.State);Assert.True(States.EmployeeEdit(r.State));Assert.False(States.EmployeeEdit(States.Rejected));Assert.Equal("Returned",task.State);Assert.Single(await db.Decisions.ToListAsync());frozen.ManagerId="tamper";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
 [Fact]public async Task MaterialCorrectionRequiresConfirmationThenCreatesNewTask(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var route=await ApprovalWorkflow.Resolve(db,employee.Id,DateOnly.FromDateTime(DateTime.UtcNow));var r=new Report{EmployeeId=employee.Id,ManagerId=route.Manager.Id,State=States.Finance,Lines=[new(){EstimatedRon=100,Json=Serialization.Write(Data(100))}]};db.Reports.Add(r);var svc=new Reports(db);svc.Snapshot(r,Actor(employee.Id,"Employee"));await db.SaveChangesAsync();r.Lines[0].Json=Serialization.Write(Data(151));r.Lines[0].EstimatedRon=151;var error=await Assert.ThrowsAsync<DomainException>(()=>svc.Reapproval(r,Actor("finance","Finance")));Assert.Equal("reapproval_confirmation",error.Code);Assert.Equal(1,r.Revision);await svc.Reapproval(r,Actor("finance","Finance"),true);await db.SaveChangesAsync();Assert.Equal(2,r.Revision);Assert.Equal(States.Reapproval,r.State);Assert.Equal(2,await db.Snapshots.CountAsync());Assert.Single(await db.ApprovalTasks.ToListAsync());}
 [Fact]public async Task MigrationIsRepeatableAndProtectsAuthorityInDatabase(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();await SchemaUpgrades.Apply(db);await SchemaUpgrades.Apply(db);Assert.Single(await db.SchemaReleases.Where(x=>x.Id==10).ToListAsync());var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var route=await ApprovalWorkflow.Resolve(db,employee.Id,DateOnly.FromDateTime(DateTime.UtcNow));var r=new Report{EmployeeId=employee.Id,ManagerId=route.Manager.Id,State=States.Manager};db.Reports.Add(r);var svc=new Reports(db);svc.Snapshot(r,Actor(employee.Id,"Employee"));await db.SaveChangesAsync();await ApprovalWorkflow.CreateTask(db,svc,r,Actor(employee.Id,"Employee"),route);await db.SaveChangesAsync();await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("UPDATE \"ApprovalTasks\" SET \"AssigneeId\" = 'tamper'"));await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("DELETE FROM \"ApprovalRoutes\""));}
}
